import java.util.InputMismatchException;
import java.util.Scanner;

public class Main {

    static void predictChurn(int age, double charges, int tenure) {

        if (age < 18 || age > 100 ||
            charges <= 0 || tenure <= 0) {

            throw new IllegalArgumentException();
        }

        double riskScore = charges / tenure + age / 10.0;

        String prediction;

        if (riskScore > 50) {
            prediction = "High Churn Risk";
        } else if (riskScore > 20) {
            prediction = "Medium Churn Risk";
        } else {
            prediction = "Low Churn Risk";
        }

        System.out.println("Age: " + age);
        System.out.println("Monthly Charges: " + charges);
        System.out.println("Tenure: " + tenure + " months");
        System.out.println("Risk Score: " + riskScore);
        System.out.println("Prediction: " + prediction);
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        try {
            int age = sc.nextInt();
            double charges = sc.nextDouble();
            int tenure = sc.nextInt();

            predictChurn(age, charges, tenure);

        } catch (InputMismatchException e) {
            System.out.println("Error: Invalid input.");

        } catch (IllegalArgumentException e) {
            System.out.println("Error: Invalid feature values.");

        } catch (ArithmeticException e) {
            System.out.println("Error: Prediction processing error.");

        } finally {
            System.out.println("ML prediction process completed.");
        }

        sc.close();
    }
}// still error, anaylse final errors and what to do

